{
  "packet_id": "H6-T01-1",
  "claim_id": "C026",
  "status": "UNSUPPORTED",
  "claim": {
    "component_id": "C026.component",
    "value": "If bookings are too sparse to apply the persistence rule, a standardized recording and handoff trial should be chosen first.",
    "scope": "A conditional fallback; no separate numerical sparsity threshold is supplied.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "CONTEXT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P014 explicitly prescribes the fallback under sparse bookings; P011 identifies the persistence rule."
    }
  },
  "signal_basis": {
    "component_id": "C026.signal_basis",
    "value": "The booking sequence is too sparse to apply the provisional rule requiring recurrence on multiple booking days in each investigation week and the same stage having the greatest documented delay burden in both weeks.",
    "scope": "The two-week investigation; the rule supports practical selection and does not establish statistical proof or causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the sparsity condition, the rule that cannot be applied, and its explicit evidential limits."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C026.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is UNSUPPORTED."
    }
  },
  "rationale": "Insufficient bookings explain why the persistence rule cannot establish a bottleneck. They do not license prioritizing the specified combined recording and handoff trial. In particular, sparse observations do not establish a handoff problem or a reason to trial a handoff change first. P014 states that prescription without supplying an unresolved empirical relation that would warrant it. This gap concerns the choice of trial, not a demand for causal proof before any trial.",
  "uncertainty": "The prescribed fallback might prove useful, but its priority does not follow from the stipulated sparsity condition.",
  "anomalies": []
}
